import {AssigneesSection} from '@github-ui/security-products-alert-assignees/components/AssigneesSection'
import type {Assignee, CodeScanningAssigneesRepository} from './types'
import {codeScanningAlertAssigneesPath, codeScanningAvailableAssigneesPath} from '@github-ui/paths'

export interface CodeScanningAssigneesSectionProps {
  alertNumber: number
  repository: CodeScanningAssigneesRepository
  currentUser: Assignee
  assignees: Assignee[]
  readonly: boolean
  copilotAssignableAlert?: boolean
}

export function CodeScanningAssigneesSection({
  alertNumber,
  repository,
  currentUser,
  assignees,
  readonly,
  copilotAssignableAlert,
}: CodeScanningAssigneesSectionProps) {
  return (
    <AssigneesSection
      className="pt-1 mb-3"
      availableAssigneesPath={codeScanningAvailableAssigneesPath({owner: repository.ownerLogin, repo: repository.name})}
      updateAssigneesPath={codeScanningAlertAssigneesPath({
        owner: repository.ownerLogin,
        repo: repository.name,
        alertNumber,
      })}
      currentUser={currentUser}
      assignees={assignees}
      readonly={readonly}
      copilotAssignableAlert={copilotAssignableAlert}
    />
  )
}

try{ CodeScanningAssigneesSection.displayName ||= 'CodeScanningAssigneesSection' } catch {}